type UpsertGroupMappingParams struct {
	OrgID      pgtype.UUID
	OidcIssuer string
	GroupName  string
	Role       OrgRole
}

func (q *Queries) UpsertGroupMapping(ctx context.Context, arg UpsertGroupMappingParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertGroupMapping,
		arg.OrgID,
		arg.OidcIssuer,
		arg.GroupName,
		arg.Role,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertGroupMemberships = `-- name: UpsertGroupMemberships :exec
INSERT INTO org_memberships (org_id, user_id, source, group_mapping_id, role)
SELECT m.org_id, $1::uuid, 'idp_group', m.id, m.role
FROM org_group_mappings m
JOIN orgs o ON o.id = m.org_id
WHERE m.oidc_issuer = $2
  AND m.group_name = ANY ($3::text[])
  AND o.identity_mode IN ('idp', 'hybrid')
  AND o.deleted_at IS NULL
ON CONFLICT (org_id, user_id, group_mapping_id) DO UPDATE
SET role = EXCLUDED.role
WHERE org_memberships.role <> EXCLUDED.role
`

type UpsertGroupMembershipsParams struct {
	UserID     pgtype.UUID
	OidcIssuer string
	Groups     []string
}

// Grants the roles of every mapping that matches one of the user's groups,
// in orgs whose identity mode uses the IdP.
func (q *Queries) UpsertGroupMemberships(ctx context.Context, arg UpsertGroupMembershipsParams) error {
	_, err := q.db.Exec(ctx, upsertGroupMemberships, arg.UserID, arg.OidcIssuer, arg.Groups)
	return err
}
